"use client";

import { useState } from 'react';
import { Sidebar } from '@/components/sidebar';
import { useAppStore } from '@/lib/store';
import { ComicUploadForm } from '@/components/comic-upload-form';
import { IllustrationUploadForm } from '@/components/illustration-upload-form';
import { BookOpen, Plus, Trash2, Edit2, ArrowLeft, Star, MessageCircle, Share2, Info, ChevronRight, Play } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { cn } from '@/lib/utils';
import type { Comic, Illustration } from '@/lib/types';
import { useParams, useRouter } from 'next/navigation';
import Link from 'next/link';

export default function LongComicsCategoryPage() {
  const params = useParams();
  const router = useRouter();
  const categoryParam = params.category as string;
  const { comics, illustrations, isAdmin, removeComic, removeIllustration, categories } = useAppStore();
  const [showUploadForm, setShowUploadForm] = useState(false);
  const [editingItem, setEditingItem] = useState<any>(null);

  const currentCategoryObj = categories.find(c => c.id === categoryParam);
  const isSeries = currentCategoryObj?.isSeries;
  const categoryTitle = currentCategoryObj ? currentCategoryObj.label : '로그 백업';

  // Find all items belonging to this category or its subcategories
  const subCategoryIds = categories.filter(c => c.parentCategoryId === categoryParam).map(c => c.id);
  const allTargetCategoryIds = [categoryParam, ...subCategoryIds];

  const categoryComics = comics.filter(c => c.type === 'long' && allTargetCategoryIds.includes(c.category || ''));
  const categoryIllusts = illustrations.filter(c => allTargetCategoryIds.includes(c.category || ''));
  
  // For display, combine and sort or just use comics if it's a comic menu
  const isIllustMenu = currentCategoryObj?.parentMenu === 'illustrations';
  const items = isIllustMenu ? categoryIllusts : categoryComics;

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm('정말로 삭제하시겠습니까?')) {
      if (isIllustMenu) removeIllustration(id);
      else removeComic(id);
    }
  };

  if (isSeries) {
    const latestItem = items[0];
    const totalCount = items.length;

    return (
      <div className="min-h-screen bg-background">
        <Sidebar />
        <main className="min-h-screen transition-all duration-300 pt-16 lg:pt-0">
          {/* Kakao Page Style Hero Section */}
          <div className="relative w-full aspect-[16/9] md:aspect-[21/9] lg:aspect-[3/1] bg-slate-900 overflow-hidden">
             {latestItem ? (
               <img src={latestItem.thumbnailUrl || (latestItem as any).images?.[0]} className="w-full h-full object-cover opacity-60 blur-sm scale-105" alt="bg" />
             ) : (
               <div className="w-full h-full bg-gradient-to-br from-blue-900 to-indigo-900" />
             )}
             <div className="absolute inset-0 bg-gradient-to-t from-background via-background/20 to-transparent" />
             
             <div className="absolute bottom-0 left-0 w-full px-6 py-8 md:px-12 md:py-12 flex flex-col md:flex-row items-end md:items-center gap-6 max-w-7xl mx-auto">
               <div className="w-32 md:w-48 aspect-[3/4] rounded-lg overflow-hidden shadow-2xl border border-white/10 z-10 shrink-0">
                 <img src={latestItem?.thumbnailUrl || (latestItem as any).images?.[0] || 'https://via.placeholder.com/300x400'} className="w-full h-full object-cover" alt="poster" />
               </div>
               <div className="flex-1 z-10 text-white">
                 <div className="flex items-center gap-2 mb-2">
                   <span className="bg-yellow-400 text-black text-[10px] font-black px-1.5 py-0.5 rounded">UP</span>
                   <span className="text-xs font-bold text-white/80">{currentCategoryObj?.parentMenu === 'illustrations' ? 'ILLUSTRATION' : 'COMICS'}</span>
                 </div>
                 <h1 className="text-3xl md:text-5xl font-black mb-3 tracking-tight">{categoryTitle}</h1>
                 <div className="flex items-center gap-4 text-sm font-medium text-white/70 mb-6">
                    <span className="flex items-center gap-1"><Star className="w-4 h-4 text-yellow-500 fill-yellow-500" /> 9.9</span>
                    <span>쟈몽</span>
                    <span>전체 {totalCount}화</span>
                 </div>
                 <div className="flex gap-3">
                    <Button 
                      className="rounded-full px-8 bg-yellow-400 hover:bg-yellow-500 text-black font-bold h-12"
                      onClick={() => {
                        if (latestItem) router.push(`/illustrations/${categoryParam}/${latestItem.id}`);
                      }}
                    >
                      <Play className="w-4 h-4 mr-2 fill-current" />
                      첫화보기
                    </Button>
                    {isAdmin && (
                       <Button variant="outline" className="rounded-full border-white/20 bg-white/10 backdrop-blur-md text-white hover:bg-white/20 h-12" onClick={() => setShowUploadForm(true)}>
                         <Plus className="w-4 h-4 mr-2" /> 작품 추가
                       </Button>
                    )}
                 </div>
               </div>
             </div>
          </div>

          <div className="max-w-7xl mx-auto px-4 md:px-8 py-8">
            <Tabs defaultValue="episodes" className="w-full">
              <TabsList className="w-full justify-start bg-transparent h-auto border-b rounded-none p-0 mb-6 gap-8">
                <TabsTrigger value="episodes" className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:bg-transparent px-0 py-3 text-lg font-bold">회차</TabsTrigger>
                <TabsTrigger value="info" className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:bg-transparent px-0 py-3 text-lg font-bold">정보</TabsTrigger>
                <TabsTrigger value="comments" className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:bg-transparent px-0 py-3 text-lg font-bold">댓글</TabsTrigger>
              </TabsList>

              <TabsContent value="episodes" className="m-0">
                 {isAdmin && showUploadForm && (
                   <div className="mb-8 p-6 bg-muted/30 rounded-2xl border">
                      {isIllustMenu ? (
                        <IllustrationUploadForm category={categoryParam} onClose={() => setShowUploadForm(false)} />
                      ) : (
                        <ComicUploadForm type="long" category={categoryParam} onClose={() => setShowUploadForm(false)} />
                      )}
                   </div>
                 )}

                 <div className="flex items-center justify-between mb-4 px-2">
                    <span className="text-sm font-bold">전체 ({totalCount})</span>
                    <Button variant="ghost" size="sm" className="text-xs font-bold">최신순 ↓</Button>
                 </div>

                 <div className="grid gap-1">
                    {items.map((item, idx) => (
                      <div 
                        key={item.id} 
                        onClick={() => router.push(`/illustrations/${categoryParam}/${item.id}`)}
                        className="group flex items-center gap-4 p-3 hover:bg-muted/50 rounded-xl cursor-pointer transition-colors border-b"
                      >
                         <div className="w-24 md:w-32 aspect-video shrink-0 overflow-hidden rounded-lg bg-slate-100 border">
                            <img src={item.thumbnailUrl || (item as any).images?.[0]} className="w-full h-full object-cover group-hover:scale-105 transition-transform" alt="thum" />
                         </div>
                         <div className="flex-1 min-w-0 py-1">
                            <h4 className="font-bold truncate group-hover:text-primary transition-colors">{totalCount - idx}화. {item.title}</h4>
                            <p className="text-xs text-muted-foreground mt-1">{new Date(item.createdAt).toLocaleDateString()}</p>
                         </div>
                         <div className="flex flex-col items-end gap-2 pr-2">
                            <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-tighter">Free</span>
                            {isAdmin && (
                              <button onClick={(e) => {e.stopPropagation(); if(confirm('삭제하시겠습니까?')) (isIllustMenu ? removeIllustration(item.id) : removeComic(item.id));}} className="p-1 text-destructive opacity-0 group-hover:opacity-100 transition-opacity">
                                <Trash2 className="w-4 h-4" />
                              </button>
                            )}
                         </div>
                      </div>
                    ))}
                 </div>
              </TabsContent>

              <TabsContent value="info" className="m-0 py-4">
                 <div className="max-w-2xl">
                    <h3 className="text-xl font-bold mb-4">작품 소개</h3>
                    <p className="text-muted-foreground leading-relaxed whitespace-pre-wrap">{currentCategoryObj?.description || '쟈몽 작가님의 연재 작품입니다.'}</p>
                 </div>
              </TabsContent>
            </Tabs>
          </div>
        </main>
      </div>
    );
  }

  // Standard Grid Layout for Non-Series
  return (
    <div className="min-h-screen bg-background">
      <Sidebar />
      <main className="min-h-screen transition-all duration-300 pt-16 lg:pt-0">
        <div className="max-w-6xl mx-auto px-6 py-12">
          <Link href={isIllustMenu ? "/illustrations" : "/comics/long"} className="mb-6 inline-flex items-center text-sm font-medium text-muted-foreground hover:text-foreground transition-colors">
            <ArrowLeft className="mr-2 h-4 w-4" />
            전체 목록으로
          </Link>
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-primary/20 flex items-center justify-center">
                <BookOpen className="w-5 h-5 text-primary" />
              </div>
              <div>
                <h1 className="text-2xl font-bold">{categoryTitle}</h1>
                <p className="text-sm text-muted-foreground">Category Items</p>
              </div>
            </div>
            {isAdmin && (
              <Button onClick={() => setShowUploadForm(!showUploadForm)}>
                <Plus className="w-4 h-4 mr-2" />
                새 작품
              </Button>
            )}
          </div>
          {isAdmin && (showUploadForm || editingItem) && (
            <div className="mb-8">
              {isIllustMenu ? (
                <IllustrationUploadForm category={categoryParam} initialData={editingItem} onClose={() => {setShowUploadForm(false); setEditingItem(null);}} />
              ) : (
                <ComicUploadForm type="long" category={categoryParam} initialData={editingItem} onClose={() => {setShowUploadForm(false); setEditingItem(null);}} />
              )}
            </div>
          )}
          {items.length > 0 ? (
            <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 lg:grid-cols-6 gap-x-4 gap-y-8">
              {items.map((item, idx) => (
                <div
                  key={item.id}
                  onClick={() => router.push(`/illustrations/${categoryParam}/${item.id}`)}
                  className="group relative cursor-pointer flex flex-col"
                >
                  <div className="aspect-[3/4] rounded-md overflow-hidden bg-slate-100 border border-slate-200/60 shadow-sm relative">
                    <img
                      src={item.thumbnailUrl || (item as any).images?.[0]}
                      alt={item.title}
                      className="w-full h-full object-cover transition-transform group-hover:scale-105"
                    />
                    <div className="absolute inset-0 bg-black/5 opacity-0 group-hover:opacity-100 transition-opacity z-10" />
                  </div>
                  <div className="mt-2.5">
                    <h3 className="text-sm font-bold text-slate-800 dark:text-slate-200 line-clamp-2 leading-tight group-hover:text-blue-600 transition-colors">
                      {item.title}
                    </h3>
                    <p className="text-[11px] text-slate-500 mt-1 flex items-center gap-1 font-medium">
                      쟈몽 <span className="w-0.5 h-0.5 rounded-full bg-slate-300 dark:bg-slate-700"></span> 작품
                    </p>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center py-20 text-center">
              <div className="w-16 h-16 rounded-2xl bg-muted flex items-center justify-center mb-4">
                <BookOpen className="w-8 h-8 text-muted-foreground" />
              </div>
              <h3 className="text-lg font-medium mb-2">아직 등록된 작품이 없습니다</h3>
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

