"use client";

import { useState, useRef } from 'react';
import { useAppStore } from '@/lib/store';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Upload, X, Image as ImageIcon, Save, GripVertical } from 'lucide-react';

import { MediaRenderer } from '@/components/media-renderer';
import { HtmlLogPreview } from '@/components/html-log-preview';
import type { Illustration } from '@/lib/types';
import { useToast } from "@/hooks/use-toast";

interface IllustrationUploadFormProps {
  onClose: () => void;
  category?: 'commission' | 'personal' | string;
  initialData?: Illustration;
}

export function IllustrationUploadForm({ onClose, category = 'personal', initialData }: IllustrationUploadFormProps) {
  const { addIllustration, updateIllustration } = useAppStore();
  const { toast } = useToast();
  const editMode = !!initialData;
  const [title, setTitle] = useState(initialData?.title || '');
  const [description, setDescription] = useState(initialData?.description || '');
  const [images, setImages] = useState<string[]>(initialData?.images || []);
  const [htmlLogs, setHtmlLogs] = useState<string[]>(initialData?.htmlLogs || []);
  const [htmlQueue, setHtmlQueue] = useState<string[]>([]);
  const [tags, setTags] = useState<string[]>(initialData?.tags || []);
  const [tagInput, setTagInput] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // HTML5 Drag and drop state
  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  const handleTagAdd = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' || e.key === ',') {
      e.preventDefault();
      const newTag = tagInput.trim().replace(/^#/, '');
      if (newTag && !tags.includes(newTag)) {
        setTags([...tags, newTag]);
      }
      setTagInput('');
    }
  };

  const removeTag = (index: number) => {
    setTags(tags.filter((_, i) => i !== index));
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);
    
    files.forEach((file) => {
      const reader = new FileReader();
      if (file.name.endsWith('.html')) {
        reader.onload = (event) => {
          const result = event.target?.result as string;
          setHtmlQueue(prev => [...prev, result]);
        };
        reader.readAsText(file);
      } else {
        reader.onload = (event) => {
          const result = event.target?.result as string;
          setImages(prev => [...prev, result]);
        };
        reader.readAsDataURL(file);
      }
    });

    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleHtmlDone = (finalHtmls: string[]) => {
    setHtmlLogs(prev => [...prev, ...finalHtmls]);
    setHtmlQueue([]);
  };

  const removeImage = (index: number) => {
    setImages(prev => prev.filter((_, i) => i !== index));
  };
  
  const removeHtml = (index: number) => {
    setHtmlLogs(prev => prev.filter((_, i) => i !== index));
  };

  const moveImage = (fromIndex: number, toIndex: number) => {
    setImages(prev => {
      const newImages = [...prev];
      const [removed] = newImages.splice(fromIndex, 1);
      newImages.splice(toIndex, 0, removed);
      return newImages;
    });
  };

  const handleDragStart = (index: number) => {
    dragItem.current = index;
  };

  const handleDragEnter = (index: number) => {
    dragOverItem.current = index;
  };

  const handleDragEnd = () => {
    if (dragItem.current !== null && dragOverItem.current !== null && dragItem.current !== dragOverItem.current) {
      moveImage(dragItem.current, dragOverItem.current);
    }
    dragItem.current = null;
    dragOverItem.current = null;
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim() || images.length === 0) return;

    setIsSaving(true);
    
    // Simulate save delay
    await new Promise(resolve => setTimeout(resolve, 500));

    if (editMode && initialData) {
      updateIllustration(initialData.id, {
        title: title.trim(),
        description: description.trim(),
        thumbnailUrl: images[0] || '',
        images,
        htmlLogs,
        category: initialData.category || category,
        tags,
      });
    } else {
      addIllustration({
        id: Date.now().toString(),
        title: title.trim(),
        description: description.trim(),
        thumbnailUrl: images[0] || '',
        images,
        htmlLogs,
        category,
        tags,
        createdAt: new Date().toISOString(),
      });
    }

    toast({
      title: editMode ? "일러스트가 수정되었습니다." : "새 일러스트가 업로드되었습니다.",
      description: "작업을 성공적으로 저장했습니다.",
    });

    setTitle('');
    setDescription('');
    setTags([]);
    setTagInput('');
    setImages([]);
    setHtmlLogs([]);
    setIsSaving(false);
    onClose();
  };

  return (
    <div className="p-6 rounded-2xl bg-card border border-border">
      <div className="flex items-center justify-between mb-6">
        <h2 className="text-lg font-semibold">{editMode ? '일러스트 수정' : '새 일러스트 업로드'}</h2>
        <button onClick={onClose} className="p-1 hover:bg-muted rounded-lg">
          <X className="w-5 h-5" />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        {/* Title */}
        <div className="space-y-2">
          <Label htmlFor="title">제목</Label>
          <Input
            id="title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="일러스트 제목을 입력하세요"
            className="bg-input"
            required
          />
        </div>

        {/* Description */}
        <div className="space-y-2">
          <Label htmlFor="description">설명</Label>
          <Textarea
            id="description"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder="일러스트에 대한 설명을 작성하세요"
            rows={3}
            className="resize-none bg-input"
          />
        </div>

        {/* Tags */}
        <div className="space-y-2">
          <Label htmlFor="tags">태그 (Enter 혹은 쉼표로 구분)</Label>
          <Input
            id="tags"
            value={tagInput}
            onChange={(e) => setTagInput(e.target.value)}
            onKeyDown={handleTagAdd}
            placeholder="예: 팬아트, 수채화, 캐릭터"
            className="bg-input"
          />
          {tags.length > 0 && (
            <div className="flex flex-wrap gap-2 mt-2">
              {tags.map((tag, index) => (
                <span
                  key={index}
                  className="inline-flex items-center gap-1 px-2.5 py-1 rounded-md bg-primary/40 text-foreground text-sm font-semibold"
                >
                  #{tag}
                  <button
                    type="button"
                    onClick={() => removeTag(index)}
                    className="hover:text-destructive transition-colors ml-1"
                  >
                    <X className="w-3 h-3" />
                  </button>
                </span>
              ))}
            </div>
          )}
        </div>

        {/* Image Upload */}
        <div className="space-y-2">
          <Label>이미지/로그 (webp, jpg, png, html, mp4 등 복수 선택 가능)</Label>
          <input
            ref={fileInputRef}
            type="file"
            accept=".webp,.jpg,.jpeg,.png,.apng,.gif,.mp4,.html,image/*,video/mp4"
            multiple
            onChange={handleImageUpload}
            className="hidden"
          />
          
          <div className="space-y-2">
            {htmlQueue.length > 0 && (
              <HtmlLogPreview 
                rawHtmls={htmlQueue} 
                onDone={handleHtmlDone} 
                onCancel={() => setHtmlQueue([])} 
              />
            )}

            {images.map((img, index) => (
              <div 
                key={index} 
                draggable
                onDragStart={() => handleDragStart(index)}
                onDragEnter={() => handleDragEnter(index)}
                onDragEnd={handleDragEnd}
                onDragOver={handleDragOver}
                className="flex items-center gap-2 p-2 rounded-lg bg-muted/50 cursor-move hover:bg-muted transition-colors"
              >
                <GripVertical className="w-4 h-4 text-muted-foreground" />
                <div className="w-12 h-16 object-cover rounded overflow-hidden drag-none pointer-events-none">
                  <MediaRenderer src={img} alt={`이미지 ${index + 1}`} className="w-full h-full object-cover" />
                </div>
                <div className="flex-1 pointer-events-none">
                  <span className="text-sm font-medium">이미지 {index + 1}</span>
                  {index === 0 && (
                    <span className="ml-2 text-xs px-1.5 py-0.5 rounded bg-primary text-primary-foreground">
                      썸네일
                    </span>
                  )}
                </div>
                <div className="flex gap-1">
                  {index > 0 && (
                    <button
                      type="button"
                      onClick={(e) => { e.stopPropagation(); moveImage(index, index - 1); }}
                      className="p-1 text-xs hover:bg-muted-foreground/20 rounded cursor-pointer"
                    >
                      위로
                    </button>
                  )}
                  {index < images.length - 1 && (
                    <button
                      type="button"
                      onClick={(e) => { e.stopPropagation(); moveImage(index, index + 1); }}
                      className="p-1 text-xs hover:bg-muted-foreground/20 rounded cursor-pointer"
                    >
                      아래로
                    </button>
                  )}
                  <button
                    type="button"
                    onClick={(e) => { e.stopPropagation(); removeImage(index); }}
                    className="p-1 text-xs text-destructive hover:bg-destructive/20 rounded cursor-pointer"
                  >
                    삭제
                  </button>
                </div>
              </div>
            ))}

            {htmlLogs.map((log, index) => (
              <div 
                key={`html-${index}`}
                className="flex items-center gap-2 p-2 rounded-lg bg-blue-500/10 border border-blue-500/20"
              >
                <div className="w-10 h-10 flex items-center justify-center bg-blue-500/20 rounded">
                  <span className="text-[10px] font-bold text-blue-500">HTML</span>
                </div>
                <div className="flex-1">
                  <span className="text-sm font-medium">로그 데이터 {index + 1}</span>
                </div>
                <button
                  type="button"
                  onClick={() => removeHtml(index)}
                  className="p-1 text-xs text-destructive hover:bg-destructive/20 rounded"
                >
                  삭제
                </button>
              </div>
            ))}
            
            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              className="w-full py-4 rounded-lg border-2 border-dashed border-border hover:border-primary flex flex-col items-center justify-center gap-1 transition-colors"
            >
              <Upload className="w-5 h-5 text-muted-foreground" />
              <span className="text-xs text-muted-foreground">이미지 추가</span>
            </button>
          </div>
          <p className="text-xs text-muted-foreground">
            첫 번째 이미지가 썸네일로 사용됩니다. 드래그하여 순서를 변경할 수 있습니다.
          </p>
        </div>

        {/* Submit */}
        <div className="flex justify-end gap-2 pt-2">
          <Button type="button" variant="outline" onClick={onClose}>
            취소
          </Button>
          <Button type="submit" disabled={isSaving || !title.trim() || images.length === 0}>
            <Save className="w-4 h-4 mr-2" />
            {isSaving ? '저장 중...' : editMode ? '수정 완료' : '업로드'}
          </Button>
        </div>
      </form>
    </div>
  );
}
